import Link from "next/link";

export const metadata = { title: "Кэш — Drop Sherlock" };

export default function CacheDoc() {
  return (
    <div className="docs-content">
      <h1>Кэш</h1>
      <p>
        Кэш — это переиспользование результатов прошлых запусков. Ahrefs
        стоит юнитов, ИИ — токенов. Если параметры точно совпадают со
        старым запуском, нет смысла платить дважды. Drop Sherlock
        автоматически переносит данные из подходящих прошлых RunDomain в
        новый — с явной отметкой «откуда».
      </p>

      <h2>Два уровня кэша</h2>
      <p>Кэш работает раздельно по двум осям:</p>
      <ul>
        <li>
          <strong>Кэш данных (Ahrefs / Wayback CDX и V2)</strong>. Ключ —
          хеш параметров запроса (URL, фильтры, сорт). Если домен в прошлой
          задаче запрашивался ровно с теми же параметрами, его сырая выдача
          копируется без обращения к Ahrefs. В CR-строке появляется{" "}
          <code>cached_from_run_id</code> и фиолетовая пилюля «Reused from
          Run #N».
        </li>
        <li>
          <strong>Кэш ИИ-вердиктов</strong>. Ключ — хеш{" "}
          <em>системного промпта</em> + provider + model + fields_sent. Если
          ничего из этого не поменялось, вердикт копируется один-в-один. В
          CR-строке появляется <code>ai_cached_from_run_id</code>; кост
          фиксируется как $0.00 (вы за этот вердикт не платили <em>в этом</em>{" "}
          запуске).
        </li>
      </ul>
      <p>
        Эти оси независимы. Возможно «данные из кэша, ИИ свежий» (например,
        вы поменяли промпт после первого прогона). Возможно «данные свежие,
        но в кэше нашёлся идентичный вердикт прошлой модели» — редко, но
        тоже бывает.
      </p>

      <h2>Где включается</h2>
      <p>
        На странице <Link href="/docs/analyze">Анализа</Link> два флажка:
      </p>
      <ul>
        <li>
          <strong>use_cache</strong> — поиск в кэше только в пределах{" "}
          <em>этой</em> задачи (Job). По умолчанию <em>включён</em> на
          rerun. Для совершенно новой задачи не имеет смысла — кэшу неоткуда
          взяться.
        </li>
        <li>
          <strong>cross_job_cache</strong> — расширяет поиск на все
          задачи. По умолчанию <em>выключен</em>. Включается автоматически,
          когда вы пришли в Анализ через «Analyze selected» из{" "}
          <Link href="/docs/database">Базы</Link>: там предполагается, что
          вы хотите переиспользовать всё уже собранное.
        </li>
      </ul>

      <h2>Что считается «совпадением»</h2>
      <p>
        Drop Sherlock не угадывает — он точно сравнивает хеши:
      </p>
      <ul>
        <li>
          <code>params_hash</code> — хеш URL Ahrefs-запроса (включая
          фильтры, сорт, лимит). Меняется, если вы поменяли{" "}
          <em>сортировку</em> критерия на странице Анализа или включили
          другой фильтр. Тогда данные перекачиваются.
        </li>
        <li>
          <code>prompt_hash</code> — хеш системного промпта (с уже
          добавленной директивой <code>localize_ru</code> для RU-запусков,
          если активна). Меняется, если вы отредактировали промпт в{" "}
          <Link href="/docs/brain">Brain</Link>. Тогда ИИ-судья
          вызывается заново. Также меняется, если выбрали{" "}
          <em>другую модель</em> или <em>другого провайдера</em> — модель и
          провайдер тоже входят в хеш.
        </li>
      </ul>

      <h2>Как не запутаться</h2>
      <p>
        Полезные индикаторы:
      </p>
      <ul>
        <li>
          На <Link href="/docs/run">странице запуска</Link> в строках доменов
          у которых данные пришли из кэша, видны соответствующие пилюли в
          колонках критериев.
        </li>
        <li>
          В{" "}
          <Link href="/docs/domain">странице домена</Link> над каждой
          таблицей сырых строк или над таймлайном Wayback стоит фиолетовая
          пилюля «Reused from Run #N» — клик ведёт на исходный запуск.
        </li>
        <li>
          В{" "}
          <Link href="/docs/database">Базе</Link> есть фильтр <em>Cache</em>{" "}
          (cached / fresh / any). Удобно, если вы хотите видеть только
          домены, у которых данные действительно свежие.
        </li>
        <li>
          В колонке стоимости на странице запуска cache-hit домены имеют
          $0 (вы за них в этом запуске не платили).
        </li>
      </ul>

      <h2>Когда кэш специально бить</h2>
      <ul>
        <li>
          Когда Ahrefs обновил данные и вы хотите свежий снимок (например,
          вы анализировали домен месяц назад). Выключите{" "}
          <code>use_cache</code> и <code>cross_job_cache</code>.
        </li>
        <li>
          Когда поменяли промпт или модель и вам нужны новые ИИ-вердикты
          (хеш промпта поменялся — кэш ИИ автоматически промахнётся, но
          Ahrefs-данные останутся из кэша, если их не отключать).
        </li>
        <li>
          Никогда — для wayback-сэмплов. Их сбор Drop Sherlock делает
          один раз и потом копирует, потому что Wayback не меняется
          ретроспективно.
        </li>
      </ul>

      <h2>Augmentation vs cache</h2>
      <p>
        Не путайте кэш с{" "}
        <Link href="/docs/augmentation">augmentation</Link>. Augmentation
        — это когда вы запустили <em>частичный</em> анализ (например,
        только <code>wayback_classify</code>), и Drop Sherlock явно
        привязал новый RunDomain к старому полному RunDomain того же
        домена, чтобы страница домена не выглядела «обрезанной». Кэш — это
        копирование одной CR-строки целиком, без привязки к родителю.
      </p>
    </div>
  );
}
